<?php
declare(strict_types=1);
require dirname(__DIR__, 2).'/espocrm/bootstrap.php';
use Espo\Core\{Application, AclManager, InjectableFactory};
use Espo\Core\ORM\EntityManager;
use Espo\Core\Tenant\{TenantContext, TenantContextStore};
use Espo\Core\Exceptions\{BadRequest, Conflict, Forbidden, NotFound};
use Espo\Custom\Tools\Conversation\ConversationService;

$app = new Application(); $app->setupSystemUser(); $c = $app->getContainer();
$em = $c->getByClass(EntityManager::class); $factory = $c->getByClass(InjectableFactory::class);
$contexts = $c->getByClass(TenantContextStore::class); $pdo = $em->getPDO(); $checks = 0;
$a = new TenantContext('30000000-0000-4000-8000-000000000001', 'isolation-alpha', 'conversation-history');
$b = new TenantContext('30000000-0000-4000-8000-000000000002', 'isolation-beta', 'conversation-history');
$call = fn ($fn) => $contexts->runWith($a, $fn); $other = fn ($fn) => $contexts->runWith($b, $fn);
$assert = function (bool $value, string $message) use (&$checks): void { $checks++; if (!$value) throw new RuntimeException($message); };
$deny = function (callable $fn, string $message) use ($assert): void { $blocked = false; try { $fn(); } catch (BadRequest|Conflict|Forbidden|NotFound $e) { $blocked = true; } $assert($blocked, $message); };
$one = function (string $sql, array $args) use ($pdo): array { $q = $pdo->prepare($sql); $q->execute($args); return $q->fetch(PDO::FETCH_ASSOC) ?: []; };
$tx = $em->getTransactionManager(); $tx->start();
try {
    $suffix = bin2hex(random_bytes(5));
    $makeUser = fn ($ctx) => $contexts->runWith($ctx, fn () => $em->createEntity('User', ['userName' => 'history-'.$ctx->slug.'-'.$suffix, 'emailAddress' => 'history-'.$ctx->slug.'-'.$suffix.'@example.test', 'type' => 'admin', 'isActive' => true]));
    $admin = $makeUser($a); $foreign = $makeUser($b);
    $admin = $call(fn () => $em->getEntityById('User', $admin->getId())); $foreign = $other(fn () => $em->getEntityById('User', $foreign->getId()));
    $build = fn ($u) => $factory->createWith(ConversationService::class, ['user' => $u, 'acl' => $c->getByClass(AclManager::class)->createUserAcl($u)]);
    $service = $build($admin); $foreignService = $build($foreign);
    $mailbox = $call(fn () => $em->createEntity('InboundEmail', ['name' => 'History group '.$suffix, 'emailAddress' => 'history-group-'.$suffix.'@example.test', 'status' => 'Inactive']));
    $make = fn ($values) => $call(fn () => $em->createEntity('Email', array_merge(['name' => 'History '.$suffix, 'status' => 'Archived', 'assignedUserId' => $admin->getId()], $values)));
    $share = fn ($email) => $call(fn () => $em->getRDBRepository('InboundEmail')->getRelation($mailbox, 'emails')->relate($email));
    $old = $make(['body' => 'PRIVATE ANCESTOR']);
    $shared = $make(['body' => 'Shared historical question', 'repliedId' => $old->getId(), 'conversationStatus' => 'Closed']); $share($shared);
    $reply = $make(['body' => 'Shared follow-up', 'repliedId' => $shared->getId()]); $share($reply);
    $sent = $make(['body' => 'Native sent response', 'status' => 'Sent', 'repliedId' => $reply->getId()]);
    $private = $make(['body' => 'PRIVATE BRANCH', 'repliedId' => $shared->getId()]);
    $privateSent = $make(['body' => 'PRIVATE BRANCH RESPONSE', 'status' => 'Sent', 'repliedId' => $private->getId()]);
    $separate = $make(['body' => 'New shared branch', 'repliedId' => $private->getId()]); $share($separate);
    $before = $one('SELECT body,status,version_number,assigned_user_id FROM email WHERE id=? AND tenant_id=? AND service_id=?', [$old->getId(), $a->tenantId, $a->serviceId]);
    $list = $call(fn () => $service->listing($suffix)); $ids = array_column($list['list'], 'id'); sort($ids); $expected = [$shared->getId(), $separate->getId()]; sort($expected);
    $assert($ids === $expected, 'Shared children of personal roots become deterministic inbox anchors without duplicate descendant rows.');
    $thread = $call(fn () => $service->thread($reply->getId()));
    $assert($thread['conversation']['id'] === $shared->getId(), 'Existing native reply links reconcile to the earliest shared anchor.');
    $visible = array_column($thread['messages'], 'id'); sort($visible); $expected = [$shared->getId(), $reply->getId(), $sent->getId()]; sort($expected);
    $assert($visible === $expected && !str_contains(json_encode($thread), 'PRIVATE'), 'Private ancestors, branches and branch replies never appear in shared history.');
    $assert($thread['conversation']['conversationStatus'] === 'Closed', 'Reading historical relationships does not reopen or modify the original triage state.');
    $assert($call(fn () => $service->thread($separate->getId()))['conversation']['id'] === $separate->getId(), 'A private incoming bridge starts a separate shared branch instead of joining private history.');
    $deny(fn () => $call(fn () => $service->thread($old->getId())), 'A personal ancestor cannot be opened through a shared child.');
    $deny(fn () => $call(fn () => $service->thread($private->getId())), 'A guessed private descendant ID cannot resolve into a shared thread.');
    $deny(fn () => $call(fn () => $service->thread($privateSent->getId())), 'A sent reply below a private incoming boundary remains outside the shared thread.');
    $after = $one('SELECT body,status,version_number,assigned_user_id FROM email WHERE id=? AND tenant_id=? AND service_id=?', [$old->getId(), $a->tenantId, $a->serviceId]);
    $assert($before === $after, 'Reconciliation is read-only: personal body, status, revision and owner remain unchanged.');
    $assert(!$one('SELECT email_id FROM email_inbound_email WHERE email_id=? AND tenant_id=? AND service_id=? AND deleted=0', [$old->getId(), $a->tenantId, $a->serviceId]), 'Historical discovery never promotes the personal ancestor into a group mailbox.');
    $cursor = $call(fn () => $service->listing($suffix, $reply->getId()));
    $assert(array_column($cursor['list'], 'id') === [$shared->getId()], 'Cursor boundaries skip already-grouped descendants without losing their older shared anchor.');
    $call(fn () => $em->getRDBRepository('Email')->getRelation($shared, 'users')->relate($admin, ['isRead' => false]));
    $call(fn () => $em->getRDBRepository('Email')->getRelation($private, 'users')->relate($admin, ['isRead' => false]));
    $call(fn () => $service->markRead($reply->getId()));
    $read = $one('SELECT is_read FROM email_user WHERE email_id=? AND user_id=? AND tenant_id=? AND service_id=? AND deleted=0', [$private->getId(), $admin->getId(), $a->tenantId, $a->serviceId]);
    $assert((int) $read['is_read'] === 0, 'Reading shared history does not touch private branch read receipts.');
    $role = $call(fn () => $em->createEntity('Role', ['name' => 'History own mail '.$suffix, 'data' => ['Email' => ['read' => 'own', 'edit' => 'no', 'create' => 'no', 'delete' => 'no']]]));
    $owner = $call(fn () => $em->createEntity('User', ['userName' => 'history-owner-'.$suffix, 'emailAddress' => 'history-owner-'.$suffix.'@example.test', 'type' => 'regular', 'isActive' => true]));
    $call(fn () => $em->getRDBRepository('User')->getRelation($owner, 'roles')->relate($role));
    $call(fn () => $em->getRDBRepository('Email')->getRelation($reply, 'users')->relate($owner, ['isRead' => false]));
    $owner = $call(fn () => $em->getEntityById('User', $owner->getId())); $ownService = $build($owner);
    $permitted = $call(fn () => $factory->create(\Espo\Core\Record\ServiceFactory::class)->createForUser('Email', $owner)->getEntity($reply->getId()));
    $assert($permitted && $permitted->getId() === $reply->getId(), 'Own-mail role fixture can natively read its shared descendant.');
    $deny(fn () => $call(fn () => $ownService->thread($reply->getId())), 'A readable descendant cannot bypass an unreadable canonical shared ancestor.');

    $incoming = $call(fn () => $em->createEntity('Email', ['name' => 'History receipt '.$suffix, 'status' => 'Archived', 'repliedId' => $shared->getId()], ['isBeingImported' => true]));
    $assert($call(fn () => $service->thread($shared->getId()))['conversation']['conversationStatus'] === 'Closed', 'A personal import alone cannot reopen a historical shared thread.');
    $call(fn () => $em->getRDBRepository('Email')->getRelation($incoming, 'inboundEmails')->relate($mailbox));
    $assert($call(fn () => $service->thread($incoming->getId()))['conversation']['conversationStatus'] === 'Open', 'The Email-side native association completes a fresh receipt and reopens the shared anchor.');
    $closed = $call(fn () => $em->getEntityById('Email', $shared->getId())); $closed->set('conversationStatus', 'Closed'); $call(fn () => $em->saveEntity($closed));
    $version = $call(fn () => $service->thread($shared->getId()))['conversation']['versionNumber']; $share($incoming);
    $replay = $call(fn () => $service->thread($shared->getId()));
    $assert($replay['conversation']['conversationStatus'] === 'Closed' && $replay['conversation']['versionNumber'] === $version, 'Replaying the GroupAccount association cannot reopen or bump a processed receipt.');
    $audit = $one("SELECT COUNT(*) total FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND subject_id=? AND action='conversation.updated' AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json,'$.messageId'))=?", [$a->tenantId, $a->serviceId, $shared->getId(), $incoming->getId()]);
    $assert((int) $audit['total'] === 1, 'A fresh receipt produces exactly one scoped reopening audit event.');
    $expired = $call(fn () => $em->createEntity('Email', ['name' => 'Expired personal receipt', 'status' => 'Archived', 'repliedId' => $shared->getId()], ['isBeingImported' => true]));
    $q = $pdo->prepare('UPDATE email SET conversation_import_pending_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 11 MINUTE) WHERE id=? AND tenant_id=? AND service_id=?'); $q->execute([$expired->getId(), $a->tenantId, $a->serviceId]); $share($expired);
    $assert($call(fn () => $service->thread($shared->getId()))['conversation']['conversationStatus'] === 'Closed', 'Later historical association of an expired personal import does not reopen old work.');
    $pending = $one('SELECT conversation_import_pending_at pending FROM email WHERE id=? AND tenant_id=? AND service_id=?', [$expired->getId(), $a->tenantId, $a->serviceId]);
    $assert($pending['pending'] === null, 'Expired receipt markers are consumed without rewriting the message.');
    $retry = $call(fn () => $em->createEntity('Email', ['name' => 'Receipt rollback', 'status' => 'Archived', 'repliedId' => $shared->getId()], ['isBeingImported' => true]));
    $pdo->exec('SAVEPOINT receipt_acceptance'); $share($retry);
    $assert($call(fn () => $service->thread($shared->getId()))['conversation']['conversationStatus'] === 'Open', 'Receipt processing participates in the native association transaction.');
    $pdo->exec('ROLLBACK TO SAVEPOINT receipt_acceptance'); $pdo->exec('RELEASE SAVEPOINT receipt_acceptance');
    $assert($call(fn () => $service->thread($shared->getId()))['conversation']['conversationStatus'] === 'Closed', 'Rolling back association also rolls back reopening and its audit.');
    $share($retry);
    $audit = $one("SELECT COUNT(*) total FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND subject_id=? AND action='conversation.updated' AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json,'$.messageId'))=?", [$a->tenantId, $a->serviceId, $shared->getId(), $retry->getId()]);
    $assert((int) $audit['total'] === 1, 'Retrying after rollback completes once without duplicate immutable audit events.');

    $close = $call(fn () => $em->getEntityById('Email', $shared->getId())); $close->set('conversationStatus', 'Closed'); $call(fn () => $em->saveEntity($close));
    // Simulate an interrupted association hook after the native mailbox link persisted.
    $interrupted = $call(fn () => $em->createEntity('Email', ['name' => 'Interrupted receipt', 'status' => 'Archived', 'repliedId' => $shared->getId()], ['isBeingImported' => true]));
    $q = $pdo->prepare('INSERT INTO email_inbound_email (email_id,inbound_email_id,tenant_id,service_id,deleted) VALUES (?,?,?,?,0)');
    $q->execute([$interrupted->getId(), $mailbox->getId(), $a->tenantId, $a->serviceId]);
    $privatePending = $call(fn () => $em->createEntity('Email', ['name' => 'Unshared pending receipt', 'status' => 'Archived'], ['isBeingImported' => true]));
    $job = $factory->create(\Espo\Custom\Jobs\RecoverConversationReceipts::class);
    $other(fn () => $job->run());
    $assert($call(fn () => $service->thread($shared->getId()))['conversation']['conversationStatus'] === 'Closed', 'Another tenant recovery job cannot consume local pending receipts.');
    $call(fn () => $job->run());
    $recovered = $call(fn () => $service->thread($shared->getId()))['conversation'];
    $assert($recovered['conversationStatus'] === 'Open', 'The native scheduled job recovers a persisted mailbox receipt without another association event.');
    $call(fn () => $job->run());
    $assert($call(fn () => $service->thread($shared->getId()))['conversation']['versionNumber'] === $recovered['versionNumber'], 'Scheduled recovery replay cannot advance a consumed receipt again.');
    $audit = $one("SELECT COUNT(*) total FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND subject_id=? AND action='conversation.updated' AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json,'$.messageId'))=?", [$a->tenantId, $a->serviceId, $shared->getId(), $interrupted->getId()]);
    $assert((int) $audit['total'] === 1, 'Scheduled recovery produces exactly one reopening audit for the interrupted receipt.');
    $privateMarker = $one('SELECT conversation_import_pending_at pending FROM email WHERE id=? AND tenant_id=? AND service_id=?', [$privatePending->getId(), $a->tenantId, $a->serviceId]);
    $assert($privateMarker['pending'] !== null, 'Recovery never consumes personal-only import markers or promotes them into shared work.');

    $betaMailbox = $other(fn () => $em->createEntity('InboundEmail', ['name' => 'Beta history', 'status' => 'Inactive']));
    $betaId = 'history'.bin2hex(random_bytes(5));
    $q = $pdo->prepare("INSERT INTO email (id,tenant_id,service_id,name,body,status,replied_id,deleted) VALUES (?,?,?,'Beta-only message','Beta content','Archived',?,0)"); $q->execute([$betaId, $b->tenantId, $b->serviceId, $shared->getId()]);
    $betaEmail = $other(fn () => $em->getEntityById('Email', $betaId)); $other(fn () => $em->getRDBRepository('InboundEmail')->getRelation($betaMailbox, 'emails')->relate($betaEmail));
    $beta = $other(fn () => $foreignService->thread($betaId));
    $assert(array_column($beta['messages'], 'id') === [$betaId] && !str_contains(json_encode($beta), $shared->getId()), 'Even a corrupt cross-tenant repliedId cannot reveal another tenant or promote its root.');
    $deny(fn () => $call(fn () => $service->thread($betaId)), 'Historical reconstruction keeps direct cross-tenant denial.');
    $assert(!in_array($betaId, array_column($call(fn () => $service->thread($shared->getId()))['messages'], 'id'), true), 'Foreign descendants cannot join a local shared thread.');
    $privateOriginal = $make(['name' => 'Private sent original', 'body' => 'PRIVATE SENT ORIGINAL', 'status' => 'Sent']);
    $firstShared = $make(['name' => 'Sent-origin history '.$suffix, 'body' => 'Shared answer', 'repliedId' => $privateOriginal->getId()]); $share($firstShared);
    $sentOrigin = $call(fn () => $service->thread($firstShared->getId()));
    $assert(array_column($sentOrigin['messages'], 'id') === [$firstShared->getId()], 'A personal sent ancestor before the first shared message is never promoted or displayed.');
    $newAnchor = $make(['name' => 'Regrouped history '.$suffix, 'conversationStatus' => 'Closed']); $share($newAnchor);
    $oldAnchor = $call(fn () => $em->getEntityById('Email', $shared->getId())); $oldAnchor->set('repliedId', $newAnchor->getId()); $call(fn () => $em->saveEntity($oldAnchor));
    $newState = $call(fn () => $service->thread($shared->getId()))['conversation'];
    $assert($newState['id'] === $newAnchor->getId(), 'Reading a regrouped member identifies its current canonical shared anchor.');
    $deny(fn () => $call(fn () => $service->update($shared->getId(), (object) ['conversationStatus' => 'Open', 'assignedUserId' => $newState['assignedUserId'], 'expectedOwnerId' => $newState['assignedUserId'], 'expectedStatus' => $newState['conversationStatus'], 'expectedVersion' => $newState['versionNumber']])), 'A former anchor cannot silently mutate a different conversation even with matching current state.');
    $assert($call(fn () => $service->thread($newAnchor->getId()))['conversation']['conversationStatus'] === 'Closed', 'Rejected regrouped writes leave the replacement anchor unchanged.');
    $call(fn () => $em->getRDBRepository('Email')->getRelation($shared, 'inboundEmails')->unrelate($mailbox));
    $deny(fn () => $call(fn () => $service->thread($shared->getId())), 'Unlinking mailbox membership immediately removes the old anchor from shared discovery.');
    $assert(!in_array($shared->getId(), array_column($call(fn () => $service->thread($reply->getId()))['messages'], 'id'), true), 'A still-shared descendant becomes the new anchor without revealing its now-private ancestor.');
    $cycleA = $make(['name' => 'Cycle '.$suffix]); $share($cycleA);
    $cycleB = $make(['name' => 'Cycle '.$suffix, 'repliedId' => $cycleA->getId()]); $share($cycleB);
    $q = $pdo->prepare('UPDATE email SET replied_id=? WHERE id=? AND tenant_id=? AND service_id=?'); $q->execute([$cycleB->getId(), $cycleA->getId(), $a->tenantId, $a->serviceId]);
    $deny(fn () => $call(fn () => $service->thread($cycleA->getId())), 'Cyclic historical reply chains fail closed.');
    $assert($call(fn () => $service->listing('Cycle '.$suffix))['list'] === [], 'Cyclic candidates do not break the rest of the inbox.');
    $call(fn () => $em->removeEntity($mailbox));
    $assert($call(fn () => $service->listing($suffix))['list'] === [], 'Deleted group mailboxes no longer authorize historical discovery.');
    echo "Conversation history checks passed: $checks (rollback-only).\n";
} catch (Throwable $error) { fwrite(STDERR, get_class($error).': '.$error->getMessage()."\n".$error->getTraceAsString()."\n"); throw $error; }
finally { if ($tx->isStarted()) $tx->rollback(); }
